-- Slice 1 M4: learning and assessment tables extracted from architecture 04 §4 (up to diagnosis_report).
-- Generated by scripts/extract-migration-learning.py; do not edit by hand.
CREATE TABLE learning_session (
  id                           uuid PRIMARY KEY,
  learner_id                   uuid NOT NULL REFERENCES learner(id),
  kind                         text NOT NULL CHECK (kind IN ('QUESTION_LOOP','PRACTICE')),
  origin                       text NOT NULL CHECK (origin IN ('FUNNEL','BANK','CHALLENGE','CONCEPT_LESSON','COMBINED_SET','INTAKE','DEVICE_IMPORT')),
  release_id                   uuid NOT NULL REFERENCES curriculum_release(id),
  anchor_question_revision_id  uuid REFERENCES question_revision(id),
  focus_concept_id             uuid REFERENCES concept(id),
  state                        text NOT NULL CHECK (state IN ('QUESTION','DIAGNOSING','CLARIFICATION_NEEDED','DIAGNOSIS_READY','MICROLEARNING','QUICK_CHECK','RETRY','VERIFYING','EVALUATION_FAILED','PRACTICING','COMPLETED','ABANDONED','EXPIRED')),
  state_version                bigint NOT NULL DEFAULT 1 CHECK (state_version >= 1),
  resume_state                 text CHECK (resume_state IN ('DIAGNOSING','VERIFYING')),
  outcome                      text CHECK (outcome IN ('SOLVED_FIRST_TRY','SOLVED_AFTER_LEARNING','SOLUTION_REVIEWED','PRACTICE_FINISHED')),
  active_attempt_id            uuid,
  unsuccessful_retries         smallint NOT NULL DEFAULT 0 CHECK (unsuccessful_retries >= 0),
  checkpoint                   jsonb NOT NULL DEFAULT '{}',   -- Continuation VO for UI resume (validated)
  legacy_client_session_id     text,                          -- alias used by the /v1/learning/* facade
  started_at                   timestamptz NOT NULL DEFAULT now(),
  last_activity_at             timestamptz NOT NULL DEFAULT now(),
  completed_at                 timestamptz,
  expires_at                   timestamptz NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, learner_id),
  UNIQUE (learner_id, legacy_client_session_id),
  CHECK ((kind = 'QUESTION_LOOP') = (anchor_question_revision_id IS NOT NULL)),
  CHECK ((state = 'COMPLETED') = (outcome IS NOT NULL AND completed_at IS NOT NULL)),
  CHECK ((state = 'EVALUATION_FAILED') = (resume_state IS NOT NULL))
);
CREATE UNIQUE INDEX session_device_import_once ON learning_session (legacy_client_session_id)
  WHERE origin = 'DEVICE_IMPORT';                   -- a device session is imported at most once, by any account

CREATE TABLE session_item (
  id                    uuid PRIMARY KEY,
  session_id            uuid NOT NULL REFERENCES learning_session(id),
  ordinal               smallint NOT NULL CHECK (ordinal >= 1),
  question_revision_id  uuid NOT NULL REFERENCES question_revision(id),
  role                  text NOT NULL CHECK (role IN ('PRACTICE','TRANSFER')),
  status                text NOT NULL CHECK (status IN ('PENDING','ANSWERED','SKIPPED')),
  UNIQUE (session_id, ordinal),
  UNIQUE (id, session_id)
);

CREATE TABLE lesson_assignment (
  id                 uuid PRIMARY KEY,
  session_id         uuid NOT NULL REFERENCES learning_session(id),
  lesson_id          uuid NOT NULL REFERENCES micro_lesson(id),
  lesson_revision_id uuid NOT NULL REFERENCES micro_lesson_revision(id),   -- pinned content (INV-04)
  concept_id         uuid NOT NULL REFERENCES concept(id),
  status             text NOT NULL CHECK (status IN ('ASSIGNED','IN_PROGRESS','CHECKS_PENDING','COMPLETED','SKIPPED')),
  slide_checkpoint   smallint NOT NULL DEFAULT 0 CHECK (slide_checkpoint >= 0),
  pinned_checks      jsonb NOT NULL,                  -- immutable [{microAssessmentId, questionRevisionId, required}]
  assigned_at        timestamptz NOT NULL DEFAULT now(),
  completed_at       timestamptz,
  updated_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, session_id)
);

CREATE TABLE question_attempt (
  id                    uuid PRIMARY KEY,
  session_id            uuid NOT NULL,
  learner_id            uuid NOT NULL,
  question_revision_id  uuid NOT NULL REFERENCES question_revision(id),
  kind                  text NOT NULL CHECK (kind IN ('INITIAL','CLARIFICATION','QUICK_CHECK','RETRY','PRACTICE','TRANSFER')),
  ordinal               int NOT NULL CHECK (ordinal > 0),
  session_item_id       uuid,
  assignment_id         uuid,
  micro_assessment_id   uuid REFERENCES micro_assessment(id),
  parent_attempt_id     uuid,
  response              jsonb NOT NULL,              -- StudentResponse VO
  response_purged_at    timestamptz,
  assistance            text NOT NULL CHECK (assistance IN ('NONE','HINT','LESSON','TUTOR','SOLUTION')),
  verdict               text NOT NULL DEFAULT 'PENDING' CHECK (verdict IN ('PENDING','CORRECT','INCORRECT','UNREADABLE','NOT_GRADED')),
  source                text NOT NULL CHECK (source IN ('LIVE','DEVICE_IMPORT')),
  submitted_at          timestamptz NOT NULL DEFAULT now(),
  graded_at             timestamptz,
  UNIQUE (session_id, ordinal),
  UNIQUE (id, session_id),
  UNIQUE (id, learner_id),
  FOREIGN KEY (session_id, learner_id) REFERENCES learning_session (id, learner_id),
  FOREIGN KEY (session_item_id, session_id) REFERENCES session_item (id, session_id),
  FOREIGN KEY (assignment_id, session_id) REFERENCES lesson_assignment (id, session_id),
  FOREIGN KEY (parent_attempt_id, session_id) REFERENCES question_attempt (id, session_id),
  CHECK ((kind = 'QUICK_CHECK') = (micro_assessment_id IS NOT NULL AND assignment_id IS NOT NULL)),
  CHECK (kind NOT IN ('CLARIFICATION','RETRY') OR parent_attempt_id IS NOT NULL)
);

ALTER TABLE learning_session
  ADD CONSTRAINT learning_session_active_attempt_fk
  FOREIGN KEY (active_attempt_id, id) REFERENCES question_attempt (id, session_id)
  DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE assistance_event (
  id                    uuid PRIMARY KEY,
  learner_id            uuid NOT NULL REFERENCES learner(id),
  session_id            uuid REFERENCES learning_session(id),
  concept_id            uuid REFERENCES concept(id),
  question_family_code  text,                         -- exposure applies to the whole family (A04)
  type                  text NOT NULL CHECK (type IN ('HINT_SHOWN','LESSON_VIEWED','TUTOR_HINT','FINAL_ANSWER_SHOWN','FULL_SOLUTION_SHOWN')),
  detail                jsonb NOT NULL DEFAULT '{}',  -- {hintStep} | {lessonId} | {tutorMessageId}
  source                text NOT NULL CHECK (source IN ('SERVER_DELIVERED','CLIENT_REPORTED')),
  dedupe_key            text NOT NULL,
  occurred_at           timestamptz NOT NULL DEFAULT now(),
  UNIQUE (learner_id, dedupe_key),
  CHECK (question_family_code IS NOT NULL OR concept_id IS NOT NULL)
);

CREATE TABLE diagnosis_run (
  id                    uuid PRIMARY KEY,
  attempt_id            uuid NOT NULL,
  learner_id            uuid NOT NULL,
  generation            smallint NOT NULL CHECK (generation BETWEEN 1 AND 5),
  purpose               text NOT NULL CHECK (purpose IN ('DIAGNOSIS','VERIFICATION','GRADING')),
  engine                text NOT NULL CHECK (engine IN ('DETERMINISTIC','AI_ASSISTED','EDUCATOR')),  -- EDUCATOR = staff regrade after an upheld report
  status                text NOT NULL CHECK (status IN ('QUEUED','RUNNING','COMPLETED','FAILED','CANCELLED')),
  evidence_status       text CHECK (evidence_status IN ('SUPPORTED','INSUFFICIENT_EVIDENCE')),
  verdict               text CHECK (verdict IN ('CORRECT','INCORRECT','UNREADABLE','NOT_GRADED')),
  headline              text,                         -- learner-facing summary, ≤ 120 chars
  lede                  text,                         -- ≤ 240 chars
  clarification_prompt  text,                         -- ≤ 240 chars
  recommendations       jsonb NOT NULL DEFAULT '[]',
  rubric_version        text NOT NULL,
  policy_version        text NOT NULL,
  prompt_version        text,
  model                 text,
  provenance            jsonb NOT NULL DEFAULT '{}',
  failure_code          text,
  deadline_at           timestamptz NOT NULL,
  started_at            timestamptz,
  completed_at          timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  UNIQUE (attempt_id, generation),
  UNIQUE (id, attempt_id),
  UNIQUE (id, learner_id),
  FOREIGN KEY (attempt_id, learner_id) REFERENCES question_attempt (id, learner_id),
  CHECK ((status = 'COMPLETED') = (evidence_status IS NOT NULL AND completed_at IS NOT NULL)),
  CHECK (evidence_status IS DISTINCT FROM 'INSUFFICIENT_EVIDENCE' OR clarification_prompt IS NOT NULL),
  CHECK (status <> 'FAILED' OR failure_code IS NOT NULL)
);
CREATE UNIQUE INDEX diagnosis_one_active_per_attempt ON diagnosis_run (attempt_id) WHERE status IN ('QUEUED','RUNNING');

CREATE TABLE concept_evidence (
  id                    uuid PRIMARY KEY,
  diagnosis_run_id      uuid NOT NULL,
  attempt_id            uuid NOT NULL,
  learner_id            uuid NOT NULL REFERENCES learner(id),
  concept_id            uuid NOT NULL REFERENCES concept(id),
  classification        text NOT NULL CHECK (classification IN ('UNDERSTANDING_DEMONSTRATED','MISCONCEPTION_EVIDENCED','INSUFFICIENT_EVIDENCE','NOT_ASSESSED')),
  misconception_code    text,
  source                text NOT NULL CHECK (source IN ('DETERMINISTIC','AI','EDUCATOR')),
  confidence            numeric(4,3) CHECK (confidence BETWEEN 0 AND 1),
  uncertainty_reasons   text[] NOT NULL DEFAULT '{}',
  refs                  jsonb NOT NULL DEFAULT '[]',  -- EvidenceRefs VO
  solution_path_code    text,
  rationale             text CHECK (char_length(rationale) <= 400),
  question_family_code  text NOT NULL,
  context_tag           text NOT NULL,
  transfer_eligible     boolean NOT NULL,
  mastery_eligible      boolean NOT NULL,
  eligibility_reasons   text[] NOT NULL DEFAULT '{}',
  supersedes_id         uuid REFERENCES concept_evidence(id),
  created_at            timestamptz NOT NULL DEFAULT now(),
  UNIQUE (diagnosis_run_id, concept_id),
  FOREIGN KEY (diagnosis_run_id, attempt_id) REFERENCES diagnosis_run (id, attempt_id),
  FOREIGN KEY (attempt_id, learner_id) REFERENCES question_attempt (id, learner_id),
  CHECK (classification <> 'MISCONCEPTION_EVIDENCED' OR rationale IS NOT NULL),
  CHECK (misconception_code IS NULL OR classification = 'MISCONCEPTION_EVIDENCED'),
  CHECK (NOT mastery_eligible OR classification IN ('UNDERSTANDING_DEMONSTRATED','MISCONCEPTION_EVIDENCED')),
  CHECK (NOT mastery_eligible OR source <> 'AI'),      -- INV-10: AI-only evidence never counts for mastery
  CHECK (NOT transfer_eligible OR mastery_eligible)
);

-- 04 §5 query indexes.
CREATE INDEX learning_session_resume ON learning_session(learner_id, last_activity_at DESC, id DESC);
CREATE INDEX learning_session_active ON learning_session(learner_id) WHERE state NOT IN ('COMPLETED','ABANDONED','EXPIRED');
CREATE INDEX learning_session_expiry ON learning_session(expires_at) WHERE state NOT IN ('COMPLETED','ABANDONED','EXPIRED');
CREATE INDEX question_attempt_history ON question_attempt(learner_id, submitted_at DESC);
CREATE INDEX question_attempt_revision ON question_attempt(question_revision_id);
CREATE INDEX assistance_event_family ON assistance_event(learner_id, question_family_code, occurred_at);
CREATE INDEX assistance_event_session ON assistance_event(session_id);
CREATE INDEX diagnosis_run_owner ON diagnosis_run(learner_id, created_at DESC);
CREATE INDEX diagnosis_run_stuck ON diagnosis_run(status, deadline_at) WHERE status IN ('QUEUED','RUNNING');
CREATE INDEX concept_evidence_mastery ON concept_evidence(learner_id, concept_id, created_at);
CREATE INDEX concept_evidence_attempt ON concept_evidence(attempt_id);
-- 04 conventions: every FK column that does not lead another index gets its own.
CREATE INDEX learning_session_release ON learning_session(release_id);
CREATE INDEX learning_session_anchor ON learning_session(anchor_question_revision_id) WHERE anchor_question_revision_id IS NOT NULL;
CREATE INDEX learning_session_focus ON learning_session(focus_concept_id) WHERE focus_concept_id IS NOT NULL;
CREATE INDEX learning_session_active_attempt ON learning_session(active_attempt_id) WHERE active_attempt_id IS NOT NULL;
CREATE INDEX session_item_revision ON session_item(question_revision_id);
CREATE INDEX lesson_assignment_session ON lesson_assignment(session_id);
CREATE INDEX lesson_assignment_lesson ON lesson_assignment(lesson_id);
CREATE INDEX lesson_assignment_revision ON lesson_assignment(lesson_revision_id);
CREATE INDEX lesson_assignment_concept ON lesson_assignment(concept_id);
CREATE INDEX question_attempt_item ON question_attempt(session_item_id) WHERE session_item_id IS NOT NULL;
CREATE INDEX question_attempt_assignment ON question_attempt(assignment_id) WHERE assignment_id IS NOT NULL;
CREATE INDEX question_attempt_check ON question_attempt(micro_assessment_id) WHERE micro_assessment_id IS NOT NULL;
CREATE INDEX question_attempt_parent ON question_attempt(parent_attempt_id) WHERE parent_attempt_id IS NOT NULL;
CREATE INDEX assistance_event_concept ON assistance_event(concept_id) WHERE concept_id IS NOT NULL;
CREATE INDEX concept_evidence_concept ON concept_evidence(concept_id);
CREATE INDEX concept_evidence_supersedes ON concept_evidence(supersedes_id) WHERE supersedes_id IS NOT NULL;

-- 04 §6: bounded value objects (response 4 KB; the others are small, server-written shapes).
ALTER TABLE question_attempt ADD CHECK (octet_length(response::text) <= 4096);
ALTER TABLE learning_session ADD CHECK (octet_length(checkpoint::text) <= 4096);
ALTER TABLE lesson_assignment ADD CHECK (octet_length(pinned_checks::text) <= 4096);
ALTER TABLE assistance_event ADD CHECK (octet_length(detail::text) <= 2048);
ALTER TABLE diagnosis_run ADD CHECK (octet_length(recommendations::text) <= 16384 AND octet_length(provenance::text) <= 4096);
ALTER TABLE concept_evidence ADD CHECK (octet_length(refs::text) <= 16384);

-- INV-07: a stored attempt is immutable. Grading sets verdict and graded_at once; the 180-day retention
-- purge (04 §8) replaces the response with {schemaVersion, responseType, purged: true}. Nothing else changes.
CREATE FUNCTION question_attempt_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  graded boolean := OLD.verdict = 'PENDING' AND NEW.verdict <> 'PENDING' AND OLD.graded_at IS NULL AND NEW.graded_at IS NOT NULL;
  purged boolean := OLD.response_purged_at IS NULL AND NEW.response_purged_at IS NOT NULL
    AND NEW.response = jsonb_build_object('schemaVersion', OLD.response -> 'schemaVersion', 'responseType', OLD.response -> 'responseType', 'purged', true);
BEGIN
  IF (to_jsonb(NEW) - 'verdict' - 'graded_at' - 'response' - 'response_purged_at') <> (to_jsonb(OLD) - 'verdict' - 'graded_at' - 'response' - 'response_purged_at')
     OR ((NEW.verdict, NEW.graded_at) IS DISTINCT FROM (OLD.verdict, OLD.graded_at) AND NOT graded)
     OR ((NEW.response, NEW.response_purged_at) IS DISTINCT FROM (OLD.response, OLD.response_purged_at) AND NOT purged) THEN
    RAISE EXCEPTION 'INV-07: attempt % is immutable', OLD.id USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER question_attempt_immutable BEFORE UPDATE ON question_attempt FOR EACH ROW EXECUTE FUNCTION question_attempt_immutable();

-- INV-08: terminal diagnosis runs are immutable; a re-run is a new generation.
CREATE FUNCTION diagnosis_run_terminal_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.status IN ('COMPLETED','FAILED','CANCELLED') THEN
    RAISE EXCEPTION 'INV-08: diagnosis run % is terminal', OLD.id USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER diagnosis_run_terminal_immutable BEFORE UPDATE ON diagnosis_run FOR EACH ROW EXECUTE FUNCTION diagnosis_run_terminal_immutable();

-- Evidence is append-only (03 §6). The one permitted change marks a row superseded by a regrade (06 §5.1 rule 7):
-- it loses mastery and transfer eligibility and gains the SUPERSEDED reason.
CREATE FUNCTION concept_evidence_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (to_jsonb(NEW) - 'mastery_eligible' - 'transfer_eligible' - 'eligibility_reasons') = (to_jsonb(OLD) - 'mastery_eligible' - 'transfer_eligible' - 'eligibility_reasons')
     AND NOT NEW.mastery_eligible AND NOT NEW.transfer_eligible
     AND NEW.eligibility_reasons = array_append(array_remove(OLD.eligibility_reasons, 'SUPERSEDED'), 'SUPERSEDED') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'evidence % is append-only; correct it with a superseding row', OLD.id USING ERRCODE = 'integrity_constraint_violation';
END $$;
CREATE TRIGGER concept_evidence_append_only BEFORE UPDATE ON concept_evidence FOR EACH ROW EXECUTE FUNCTION concept_evidence_append_only();
